import { ApiError } from "./http";
import trailsRaw from "./data/segments.json";
import roadsRaw from "./data/segments.roads.json";

/** [length_m, tickCount, tickLengthM, included 0|1] — generated by scripts/build-segment-meta.mjs. */
export type SegmentTuple = readonly [lengthM: number, tickCount: number, tickLengthM: number, included: number];

/** RD-7: the two goals one account can play. Coverage, metrics, leaderboard and stats are scoped by it. */
export const DATASETS = ["trails", "roads"] as const;
export type Dataset = (typeof DATASETS)[number];

export interface SegmentMeta {
  dataset: Dataset;
  version: string;
  tickM: number;
  islandTotalM: number;
  segments: Record<string, SegmentTuple>;
  /** Trail ids (roads: road ids) -> distinct segment ids. */
  trails: Record<string, string[]>;
  /** Well-formed segment id of this dataset; ids of the other dataset never match (no cross-dataset rows). */
  segmentId: RegExp;
}

interface RawMeta {
  version: string;
  tickM: number;
  islandTotalM: number;
  segments: Record<string, number[]>;
  trails: Record<string, string[]>;
}

function load(dataset: Dataset, src: RawMeta, segmentId: RegExp): SegmentMeta {
  const segments: Record<string, SegmentTuple> = {};
  for (const [id, t] of Object.entries(src.segments)) {
    const [len, n, tickLen, inc] = t;
    if (len === undefined || n === undefined || tickLen === undefined || inc === undefined) throw new Error(`bad segment meta ${id}`);
    if (!segmentId.test(id)) throw new Error(`${dataset} segment meta has foreign id ${id}`);
    segments[id] = [len, n, tickLen, inc];
  }
  return { dataset, version: src.version, tickM: src.tickM, islandTotalM: src.islandTotalM, segments, trails: src.trails, segmentId };
}

export const METAS: Record<Dataset, SegmentMeta> = {
  trails: load("trails", trailsRaw, /^seg-\d{6}$/),
  roads: load("roads", roadsRaw, /^rseg-\d{6}$/),
};

/** The trails dataset (the default everywhere `dataset` is omitted). */
export const META: SegmentMeta = METAS.trails;

/** `dataset` from a request (query or body); absent = `trails` for clients that predate RD-7. */
export function parseDataset(value: unknown): Dataset {
  if (value === undefined || value === null) return "trails";
  if (typeof value === "string" && (DATASETS as readonly string[]).includes(value)) return value as Dataset;
  throw new ApiError(400, "invalid_dataset", `dataset must be one of ${DATASETS.join(", ")}`);
}

/** D1 range bounds of a dataset's coverage rows (uses the (user_id, segment_id) primary key). */
export function segmentRange(dataset: Dataset): [lo: string, hi: string] {
  return dataset === "trails" ? ["seg-", "seg."] : ["rseg-", "rseg."];
}
